"use client";
import Hls from "hls.js";
import { useEffect, useRef, useState } from "react";

/** Watches the media generated by an explicit playback command without starting a live-camera command. */
export default function CameraRecordingPlayer({ deviceId, channel, attempt }: { deviceId: string; channel: number; attempt: number }) {
  const video = useRef<HTMLVideoElement>(null);
  const [error, setError] = useState("");
  useEffect(() => {
    const element = video.current;
    if (!element) return;
    const source = `/api/dashcams/${encodeURIComponent(deviceId)}/stream/${channel}/live.m3u8`;
    let hls: Hls | null = null, timer: ReturnType<typeof setTimeout> | undefined;
    let stopped = false;
    const deadline = Date.now() + 60000;
    const play = () => { void element.play().catch(() => { if (!stopped) setError("Tap play to watch the recording."); }); };
    function retry(load: () => void) { if (stopped) return; if (Date.now() >= deadline) { setError("No recording video received. Check the command result and camera connection."); return; } if (timer) clearTimeout(timer); timer = setTimeout(load, 2000); }
    const playing = () => { if (timer) clearTimeout(timer); setError(""); };
    const failed = () => retry(() => { element.src = source; element.load(); play(); });
    element.addEventListener("playing", playing);
    if (element.canPlayType("application/vnd.apple.mpegurl")) { element.src = source; element.addEventListener("error", failed); play(); }
    else if (Hls.isSupported()) { hls = new Hls(); hls.loadSource(source); hls.attachMedia(element); hls.on(Hls.Events.MANIFEST_PARSED, play); hls.on(Hls.Events.ERROR, (_event, data) => { if (data.fatal) retry(() => hls?.loadSource(source)); }); }
    else timer = setTimeout(() => setError("This browser cannot play camera video."), 0);
    return () => { stopped = true; if (timer) clearTimeout(timer); element.removeEventListener("playing", playing); element.removeEventListener("error", failed); hls?.destroy(); element.pause(); element.removeAttribute("src"); element.load(); };
  }, [deviceId, channel, attempt]);
  return <section className="rounded-xl border bg-black p-3 text-white"><h3 className="mb-2 text-sm font-semibold">Recording playback</h3><video ref={video} controls autoPlay muted playsInline className="aspect-video w-full" />{error && <p role="status" className="mt-2 text-sm text-amber-200">{error}</p>}<p className="mt-2 text-xs text-slate-300">Use the recording controls to pause, seek, or end playback on the camera.</p></section>;
}
